'use strict';
let pmFeed=null,pmBusy=false,pmSelected=null,pmCurrentQuote=null,pmJournal=[],pmScores={},pmTimer,pmQuoteVersion=0,pmJournalChecking=false;
const pmCents=n=>Number.isFinite(n)?(n*100).toFixed(1)+'¢':'—',pmPercent=n=>Number.isFinite(n)?(n*100).toFixed(1)+'%':'—';
function pmWords(s){return String(s||'').toLowerCase()}
function pmLocalFill(levels,budget){let left=budget,shares=0;for(const x of [...(levels||[])].sort((a,b)=>Number(a.price)-Number(b.price))){const p=Number(x.price),size=Number(x.size);if(!(p>0&&p<=1&&size>0))continue;const n=Math.min(size,left/p);shares+=n;left-=n*p;if(left<1e-8)break}return {complete:left<1e-6,shares,average:shares?(budget-left)/shares:null}}
function renderPredictions(){
 const q=pmWords($('#pmSearch').value),only=$('#pmConnected').checked,markets=(pmFeed?.value?.markets||[]).filter(m=>(!q||pmWords(m.question+' '+m.event).includes(q))&&(!only||m.connections.length));
 $('#pmStatus').textContent=pmFeed?.value?(pmFeed.stale?'Saved data · refresh failed':'Polymarket snapshot')+' · '+stamp(pmFeed.checkedAt)+' · '+markets.length+' contracts':pmFeed?.error?'Market data unavailable. Retry later; no prices are assumed.':'Loading political markets…';
 $('#pmCoverage').textContent=pmFeed?.value?.coverage||'Public market data. No wallet or real-money orders.';
 $('#pmMarkets').innerHTML=markets.map(m=>{const yes=m.outcomes.find(o=>o.label==='Yes');return `<button class="pm-market ${pmSelected?.id===m.id?'selected':''}" data-pm-market="${esc(m.id)}"><span class="pm-market-title">${esc(m.question)}</span><span class="pm-price">${pmPercent(yes?.price)}<small>Yes · indicative</small></span><span class="pm-market-meta">${m.change===null?'24h unavailable':(m.change>=0?'+':'')+(m.change*100).toFixed(1)+' pp / 24h'} · ${m.end?'Ends '+date(m.end):'End date unavailable'}</span><span class="pm-market-meta">${m.connections.length?'Related research: '+m.connections.length:'No matched research'} · $${Math.round(m.volume||0).toLocaleString()} volume / 24h</span></button>`}).join('')||`<p class="muted">${pmFeed?.value?'No contracts match these filters.':'No market feed available. Your saved forecasts remain below.'}</p>`;
}
async function loadPredictions(){if(pmBusy)return;pmBusy=true;clearTimeout(pmTimer);try{const r=await fetch('/api/predictions');if(!r.ok)throw Error();pmFeed=await r.json()}catch{pmFeed=pmFeed?.value?{...pmFeed,stale:true}:{error:true}}finally{pmBusy=false;renderPredictions();if(view==='predictions')pmTimer=setTimeout(loadPredictions,120000)}loadPredictionJournal()}
function pmConnectionHTML(m){return m.connections.length?m.connections.map(a=>`<article class="pm-evidence"><small>Shared topics: ${a.shared.map(esc).join(', ')} · ${date(a.date)}</small><h3>${esc(a.title)}</h3><p>${esc(a.summary)}</p><p><b>Inference:</b> ${esc(a.impact)}</p><p><b>Risk:</b> ${esc(a.risk)}</p><p><b>Next check:</b> ${esc(a.watch)}</p><div>${a.tickers.map(t=>`<button data-ticker="${esc(t)}">${esc(t)} ↗</button>`).join(' ')} ${a.sources.map((u,i)=>researchLink(u,'Evidence '+(i+1))).join(' · ')}</div></article>`).join(''):'<p class="muted">No recent briefing shares enough specific topics with this contract. Research is needed before estimating an edge.</p>'}
function selectPrediction(id){const m=pmFeed?.value?.markets.find(m=>m.id===id);if(!m)return;pmSelected=m;pmCurrentQuote=null;renderPredictions();$('#pmDetail').hidden=false;$('#pmDetail').innerHTML=`<div class="pm-detail-heading"><h2>${esc(m.question)}</h2><button id="pmAsk">Ask poor ↗</button></div><p class="home-caption">Research match ≠ verified causal link. Probability below is your forecast; poor does not invent one.</p><div class="pm-facts"><span>End date<b>${m.end?date(m.end):'Not supplied'}</b></span><span>Liquidity reported<b>$${Math.round(m.liquidity||0).toLocaleString()}</b></span><span>24h Yes move<b>${m.change===null?'—':(m.change>=0?'+':'')+(m.change*100).toFixed(1)+' pp'}</b></span></div><div id="pmHistory" class="pm-history">Loading 7-day Yes-price history…</div><details class="pm-rules"><summary>Resolution rules & source</summary><p>${esc(m.rules).replace(/\n/g,'<br>')}</p>${m.resolutionSource?researchLink(m.resolutionSource,'Resolution source'): '<p>Check the resolution source in the rules.</p>'} · ${researchLink(m.url,'Market rules on Polymarket')}</details><h3>Connect the evidence</h3>${pmConnectionHTML(m)}<form id="pmForecast"><h3>Lock a $100 paper forecast</h3><div class="pm-form-row"><label>Outcome<select id="pmOutcome"><option>Yes</option><option>No</option></select></label><label>Your probability (%)<input id="pmProbability" type="number" min="1" max="99" step="0.1" placeholder="Your estimate" required></label><label>Cost allowance (%)<input id="pmFee" type="number" min="0" max="10" step="0.1" value="2" required></label></div><p class="home-caption">Allowance applies to entry and an open-market exit; settlement pays $1 or $0 per share. It is an assumption, not a verified fee schedule. ${m.feesEnabled?'Provider reports fees enabled.':'Check the market’s applicable fees.'}</p><div id="pmQuote" class="pm-quote" role="status">Loading executable quote…</div><label>Why is the market mispricing this?<textarea id="pmThesis" maxlength="1200" minlength="15" rows="2" required placeholder="Evidence for your estimate, and what may already be priced in"></textarea></label><label>What would invalidate your forecast?<input id="pmInvalidation" maxlength="500" minlength="10" required placeholder="A specific observable contradiction"></label><label>Evidence links · one HTTPS URL per line<textarea id="pmSources" rows="2" required placeholder="https://…"></textarea></label><div class="pm-form-row"><button type="button" id="pmQuoteRefresh">Refresh quote</button><button class="primary" id="pmSave" disabled>Save paper forecast</button></div><p id="pmSaveStatus" role="status" class="home-caption">Sign-in required. Forecast, rules, time and entry are locked; losing entries remain in the journal.</p></form>`;
 $('#pmOutcome').onchange=refreshPredictionQuote;$('#pmQuoteRefresh').onclick=refreshPredictionQuote;$('#pmProbability').oninput=renderPredictionQuote;$('#pmFee').oninput=renderPredictionQuote;$('#pmForecast').onsubmit=savePrediction;
 $('#pmAsk').onclick=()=>{const question='Investigate this prediction market using public evidence. Explain evidence for/against, what is priced in, uncertainty and the next check. Do not invent a probability. Contract: '+m.question+'; end: '+m.end+'; rules: '+m.rules.slice(0,850)+'; source: '+m.url;changeView('chat');$('#chatQuestion').value=question.slice(0,1800);$('#chatQuestion').focus()};
 loadPredictionHistory(m);refreshPredictionQuote();if(matchMedia('(max-width: 800px)').matches)$('#pmDetail').scrollIntoView({block:'start'});
}
async function loadPredictionHistory(m){try{const r=await fetch('/api/predictions/history?id='+m.id),d=await r.json();if(pmSelected?.id!==m.id)return;const points=d.value?.points;if(!r.ok||!points||points.length<2)throw Error();const first=points[0],last=points.at(-1),width=480,height=90,coords=points.map(x=>`${((x.t-first.t)/(last.t-first.t||1)*width).toFixed(1)},${(height-x.p*height).toFixed(1)}`).join(' ');const reactions=m.connections.map(a=>{const start=Date.parse(a.date+'T00:00:00Z')/1000,before=points.filter(x=>x.t<start).at(-1);return before&&start-before.t<=86400&&last.t>=start?`<p>${esc(a.title)}: ${pmPercent(before.p)} before source day → ${pmPercent(last.p)} latest sample. ${date(a.date)}</p>`:''}).join('');$('#pmHistory').innerHTML=`<small>Yes price · 7-day history · 0–100% scale${d.stale?' · stale':''}</small><svg viewBox="0 0 ${width} ${height}" role="img" aria-label="Seven-day Yes-price history"><line x1="0" x2="480" y1="45" y2="45" stroke="#dce6df" stroke-dasharray="3 4"/><polyline points="${coords}" fill="none" stroke="#198568" stroke-width="2"/></svg><small>${date(new Date(first.t*1000).toISOString())} · ${pmPercent(first.p)} → ${pmPercent(last.p)} · ${date(new Date(last.t*1000).toISOString())}</small>${reactions}<small>Historical samples are not executable quotes. Date-only news cannot establish the exact price reaction or causation.</small>`}catch{if(pmSelected?.id===m.id)$('#pmHistory').textContent='Price history unavailable; no trend is inferred.'}}
async function refreshPredictionQuote(){const version=++pmQuoteVersion;pmCurrentQuote=null;$('#pmSave').disabled=true;$('#pmQuote').textContent='Checking order-book prices and depth…';try{const r=await fetch('/api/predictions/quote?id='+pmSelected.id+'&outcome='+$('#pmOutcome').value),d=await r.json();if(version!==pmQuoteVersion)return;if(!r.ok)throw Error(d.error||'Order book unavailable');pmCurrentQuote=d;renderPredictionQuote()}catch(e){if(version===pmQuoteVersion)$('#pmQuote').textContent=e.message+' · Paper entry disabled.'}}
function renderPredictionQuote(){const q=pmCurrentQuote;if(!q)return;const fee=Number($('#pmFee').value)/100,p=Number($('#pmProbability').value)/100,fill=pmLocalFill(q.book.asks,100/(1+fee)),fresh=Date.now()-Number(q.book.timestamp)<120000,expected=fill.shares*p-100,spread=q.ask!==null&&q.bid!==null?q.ask-q.bid:null;
 $('#pmQuote').innerHTML=`<div class="pm-facts"><span>Best buy / sell<b>${pmCents(q.ask)} / ${pmCents(q.bid)}</b></span><span>Spread<b>${pmCents(spread)}</b></span><span>$100 average entry<b>${fill.complete?pmCents(fill.average):'Insufficient depth'}</b></span></div><p>${fresh?'Quote':'Stale quote'} · ${stamp(Number(q.book.timestamp))} · ${fill.shares.toFixed(2)} simulated shares</p><p><b>${p>0&&p<1&&fill.complete?'Expected settlement P/L: '+(expected>=0?'+':'−')+'$'+Math.abs(expected).toFixed(2):'Enter your probability to estimate expected settlement P/L.'}</b></p><small>Expected value uses your assumption, not a prediction of profit. Maximum loss: $100. ${spread>.05?'Wide spread: execution costs can erase an apparent edge.':''}</small>`;$('#pmSave').disabled=!fresh||!fill.complete||!Number.isFinite(fee)||fee<0||fee>.1;
}
async function savePrediction(e){e.preventDefault();if(!pmCurrentQuote)return;$('#pmSave').disabled=true;const fee=Number($('#pmFee').value)/100,fill=pmLocalFill(pmCurrentQuote.book.asks,100/(1+fee));try{const r=await fetch('/api/predictions/journal',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({marketId:pmSelected.id,outcome:$('#pmOutcome').value,probability:Number($('#pmProbability').value)/100,fee,maxPrice:fill.average,thesis:$('#pmThesis').value,invalidation:$('#pmInvalidation').value,sources:$('#pmSources').value.split(/\n/).map(s=>s.trim()).filter(Boolean)})}),d=await r.json();if(!r.ok)throw Error(d.error||'Could not save');$('#pmSaveStatus').textContent='Forecast saved and locked. No real-money order was placed.';await loadPredictionJournal()}catch(e){$('#pmSaveStatus').textContent=e.message;renderPredictionQuote()}}
function renderPredictionJournal(){const scored=pmJournal.map(r=>({r,s:pmScores[r.id]})),resolved=scored.filter(x=>x.s?.value?.state==='Resolved'&&!x.s.stale),brier=resolved.length?resolved.reduce((n,x)=>n+x.s.value.brier,0)/resolved.length:null,pnl=resolved.reduce((n,x)=>n+x.s.value.pnl,0);
 $('#pmPerformance').innerHTML=`<span><b>${pmJournal.length}</b> locked forecasts</span><span><b>${resolved.length}</b> resolved & checked</span><span><b>${resolved.length?(pnl>=0?'+':'−')+'$'+Math.abs(pnl).toFixed(2):'—'}</b> resolved paper P/L</span><span><b>${brier===null?'—':brier.toFixed(3)}</b> Brier score · lower is better</span>`;
 $('#pmJournal').innerHTML=scored.map(({r,s})=>`<article class="pm-journal-row"><div><h3>${esc(r.question)}</h3><small>${date(r.createdAt)} · ${esc(r.outcome)} · Forecast ${pmPercent(r.probability)} · Entry ${pmCents(r.entry)} · Cost allowance ${pmPercent(r.fee)}</small></div><strong class="${s?.value?.pnl<0?'loss':'gain'}">${s?.value?.pnl!=null?(s.value.pnl>=0?'+':'−')+'$'+Math.abs(s.value.pnl).toFixed(2):'—'}<small>${esc(s?.value?.state||'Not checked')}${s?.stale?' · stale':''}</small></strong><button data-pm-score="${esc(r.id)}">Check result</button><details><summary>Locked thesis & evidence</summary><p>${esc(r.thesis)}</p><p><b>Invalidation:</b> ${esc(r.invalidation)}</p>${r.sources.map((u,i)=>researchLink(u,'Evidence '+(i+1))).join(' · ')}<p><b>Rules at entry:</b> ${esc(r.rules)}</p>${s?.value?.rulesChanged?'<p class="loss">Market rules changed since entry. Inspect the current resolution terms.</p>':''}<p>$100 per forecast. Open P/L uses available bid depth and your exit-cost assumption. Resolved P/L uses the provider-confirmed payout. No real capital is invested.</p></details></article>`).join('')||'<p class="muted">No forecasts yet. Record the evidence and probability before the outcome is known.</p>';
}
async function loadPredictionJournal(){try{const r=await fetch('/api/predictions/journal');if(r.status===401){pmJournal=[];pmScores={};$('#pmJournal').innerHTML='<p><a href="/signin-with-chatgpt?return_to=%2F">Sign in with ChatGPT</a> to keep a private paper journal across devices.</p>';$('#pmPerformance').textContent='Paper research only · no real-money orders';return}if(!r.ok)throw Error();pmJournal=(await r.json()).rows;renderPredictionJournal();if(!pmJournalChecking){pmJournalChecking=true;try{for(let i=0;i<pmJournal.length;i+=4){if(view!=='predictions')break;await Promise.all(pmJournal.slice(i,i+4).map(row=>checkPrediction(row.id)))}}finally{pmJournalChecking=false}}}catch{$('#pmJournal').textContent='Paper journal unavailable. Retry to load saved forecasts.'}}
async function checkPrediction(id){const row=pmJournal.find(r=>r.id===id);if(!row)return;const button=document.querySelector(`[data-pm-score="${id}"]`);if(button){button.disabled=true;button.textContent='Checking…'}try{const r=await fetch('/api/predictions/score?id='+row.marketId+'&entry='+row.id);if(!r.ok)throw Error();pmScores[id]=await r.json()}catch{pmScores[id]={value:{state:'Result unavailable'},stale:true}}renderPredictionJournal()}
if(typeof window!=='undefined'){
 window.addEventListener('hashchange',()=>{if(location.hash==='#predictions')changeView('predictions')});if(location.hash==='#predictions')changeView('predictions');
 $('#pmSearch').oninput=renderPredictions;$('#pmConnected').onchange=renderPredictions;$('#pmRefresh').onclick=loadPredictions;
 document.addEventListener('click',e=>{const market=e.target.closest('[data-pm-market]'),score=e.target.closest('[data-pm-score]');if(market)selectPrediction(market.dataset.pmMarket);if(score)checkPrediction(score.dataset.pmScore)});
 document.addEventListener('visibilitychange',()=>{if(!document.hidden&&view==='predictions')loadPredictions()});
}
